from collections import deque

def maxDistance(grid):
    n = len(grid)
    queue = deque()
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                queue.append((i, j))
    if not queue or len(queue) == n * n:
        return -1
    dist = -1
    while queue:
        size = len(queue)
        for _ in range(size):
            x, y = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and grid[nx][ny] == 0:
                    grid[nx][ny] = 1
                    queue.append((nx, ny))
        dist += 1
    return dist
